th=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\">\n          <line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\" />\n          <line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\" />\n        </svg>\n      </button>\n    </div>\n    <div class=\"contact-items\">\n      <div\n        v-for=\"contact in store.contacts\"\n        :key=\"contact.name\"\n        class=\"contact-item\"\n        @click=\"store.selectContact(contact.name)\"\n      >\n        <div class=\"contact-avatar-wrap\" @click.stop=\"triggerAvatarUpload(contact.name)\" title=\"点击更换头像\">\n          <img v-if=\"store.getAvatar(contact.name)\" class=\"contact-avatar-img\" :src=\"store.getAvatar(contact.name)!\" :alt=\"contact.name\" />\n          <div v-else class=\"contact-avatar-placeholder\" :style=\"{ background: avatarGradient(contact.name) }\">\n            {{ contact.avatarChar }}\n          </div>\n          <!-- 消息红点 -->\n          <span v-if=\"(store.unreadCounts[contact.name] || 0) > 0\" class=\"avatar-badge\">\n            {{ (store.unreadCounts[contact.name] || 0) > 99 ? '99+' : store.unreadCounts[contact.name] }}\n          </span>\n        </div>\n        <div class=\"contact-info\">\n          <div class=\"contact-name-row\">\n            <span class=\"contact-name\">{{ contact.name }}</span>\n          </div>\n          <div class=\"contact-preview-row\">\n            <span class=\"contact-preview\">{{ truncate(store.contactPreviews[contact.name]?.content) }}</span>\n          </div>\n        </div>\n        <button class=\"contact-delete-btn\" @click.stop=\"confirmDelete(contact.name)\" title=\"删除联系人\">\n          <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\">\n            <line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\" />\n            <line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\" />\n          </svg>\n        </button>\n      </div>\n      <div v-if=\"store.contacts.length === 0\" class=\"contact-empty\">\n        <!-- 空状态图标 -->\n        <svg class=\"empty-icon-svg\" width=\"48\" height=\"48\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <rect x=\"5\" y=\"2\" width=\"14\" height=\"20\" rx=\"2\" ry=\"2\" />\n          <line x1=\"12\" y1=\"18\" x2=\"12.01\" y2=\"18\" />\n        </svg>\n        <div class=\"empty-text\">暂无联系人</div>\n        <div class=\"empty-hint\">点击右上角 + 添加好友，或等待AI输出 &lt;iphone&gt; 标签自动添加</div>\n      </div>\n    </div>\n    <!-- 隐藏的文件选择器 -->\n    <input ref=\"avatarInputRef\" type=\"file\" accept=\"image/*\" class=\"hidden-input\" @change=\"onAvatarSelected\" />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { usePhoneStore } from '../store';\n\nconst store = usePhoneStore();\nconst avatarInputRef = ref<HTMLInputElement | null>(null);\nconst pendingAvatarName = ref('');\n\nconst gradients = [\n  'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',\n  'linear-gradient(135deg, #f093fb 0%, #f5576c 100%)',\n  'linear-gradient(135deg, #4facfe 0%, #00f2fe 100%)',\n  'linear-gradient(135deg, #43e97b 0%, #38f9d7 100%)',\n  'linear-gradient(135deg, #fa709a 0%, #fee140 100%)',\n  'linear-gradient(135deg, #a18cd1 0%, #fbc2eb 100%)',\n];\n\nfunction avatarGradient(name: string): string {\n  let hash = 0;\n  for (let i = 0; i < name.length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash);\n  return gradients[Math.abs(hash) % gradients.length];\n}\n\nfunction truncate(text?: string): string {\n  if (!text) return '';\n  return text.length > 20 ? text.slice(0, 20) + '...' : text;\n}\n\nfunction confirmDelete(name: string) {\n  if (window.parent.confirm(`确定要删除联系人「${name}」及其聊天记录吗？`)) {\n    store.removeContact(name);\n  }\n}\n\nfunction triggerAvatarUpload(name: string) {\n  pendingAvatarName.value = name;\n  avatarInputRef.value?.click();\n}\n\nasync function onAvatarSelected(e: Event) {\n  const input = e.target as HTMLInputElement;\n  const file = input.files?.[0];\n  if (!file || !pendingAvatarName.value) return;\n  await store.setAvatar(pendingAvatarName.value, file);\n  input.value = '';\n  pendingAvatarName.value = '';\n}\n</script>\n\n<style scoped>\n.contact-list {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n}\n\n.contact-header {\n  padding: 12px 16px;\n  border-bottom: 1px solid var(--border-secondary);\n  flex-shrink: 0;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.contact-header-title {\n  font-size: 16px;\n  font-weight: 600;\n  color: var(--text-primary);\n}\n\n.add-contact-btn {\n  width: 28px;\n  height: 28px;\n  border-radius: 6px;\n  border: none;\n  background: var(--bg-hover);\n  color: var(--text-tertiary);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: all 0.15s;\n}\n\n.add-contact-btn:hover {\n  background: var(--bg-active);\n  color: var(--text-secondary);\n}\n\n.contact-items {\n  flex: 1;\n  overflow-y: auto;\n  scrollbar-width: thin;\n  scrollbar-color: var(--text-hint) transparent;\n}\n\n.contact-items::-webkit-scrollbar {\n  width: 4px;\n}\n\n.contact-items::-webkit-scrollbar-thumb {\n  background: var(--text-hint);\n  border-radius: 2px;\n}\n\n.contact-item {\n  display: flex;\n  align-items: center;\n  padding: 12px 16px;\n  gap: 12px;\n  cursor: pointer;\n  transition: background 0.15s;\n  position: relative;\n}\n\n.contact-item:hover {\n  background: var(--bg-hover);\n}\n\n.contact-item:active {\n  background: var(--bg-active);\n}\n\n/* 头像容器 */\n.contact-avatar-wrap {\n  position: relative;\n  width: 44px;\n  height: 44px;\n  flex-shrink: 0;\n  cursor: pointer;\n  transition: opacity 0.15s;\n}\n\n.contact-avatar-wrap:hover {\n  opacity: 0.8;\n}\n\n.hidden-input {\n  display: none;\n}\n\n.contact-avatar-img {\n  width: 44px;\n  height: 44px;\n  border-radius: 10px;\n  object-fit: cover;\n}\n\n.contact-avatar-placeholder {\n  width: 44px;\n  height: 44px;\n  border-radius: 10px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 18px;\n  font-weight: 600;\n  color: white;\n}\n\n/* 头像右上角红点 */\n.avatar-badge {\n  position: absolute;\n  top: -4px;\n  right: -4px;\n  background: var(--danger);\n  color: white;\n  font-size: 10px;\n  font-weight: 700;\n  min-width: 18px;\n  height: 18px;\n  border-radius: 9px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 0 4px;\n  border: 2px solid var(--bg-secondary);\n  line-height: 1;\n}\n\n.contact-info {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n.contact-name-row {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.contact-name {\n  font-size: 14px;\n  font-weight: 500;\n  color: var(--text-primary);\n}\n\n.contact-preview-row {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.contact-preview {\n  font-size: 12px;\n  color: var(--text-tertiary);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  flex: 1;\n  min-width: 0;\n}\n\n.contact-delete-btn {\n  width: 22px;\n  height: 22px;\n  border-radius: 4px;\n  border: none;\n  background: transparent;\n  color: var(--text-hint);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: all 0.15s;\n  flex-shrink: 0;\n  opacity: 0;\n}\n\n.contact-item:hover .contact-delete-btn {\n  opacity: 1;\n}\n\n.contact-delete-btn:hover {\n  background: rgba(231, 76, 60, 0.15);\n  color: var(--danger);\n}\n\n.contact-empty {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  padding: 40px 20px;\n  gap: 8px;\n}\n\n.empty-icon-svg {\n  color: var(--text-muted);\n  opacity: 0.5;\n}\n\n.empty-text {\n  font-size: 14px;\n  color: var(--text-tertiary);\n}\n\n.empty-hint {\n  font-size: 11px;\n  color: var(--text-hint);\n  text-align: center;\n  line-height: 1.4;\n}\n</style>\n"],"sourceRoot":""}]);
