g-pop-enter-from[data-v-1a6c0445]{opacity:0;transform:translateY(16px) scale(0.92)}.msg-pop-leave-active[data-v-1a6c0445]{transition:all 0.2s ease}.msg-pop-leave-to[data-v-1a6c0445]{opacity:0;transform:translateY(-8px)}.msg-avatar-wrap[data-v-1a6c0445]{width:32px;height:32px;flex-shrink:0}.msg-avatar-wrap.clickable[data-v-1a6c0445]{cursor:pointer;transition:opacity 0.15s}.msg-avatar-wrap.clickable[data-v-1a6c0445]:hover{opacity:0.8}.msg-avatar-img[data-v-1a6c0445]{width:32px;height:32px;border-radius:6px;object-fit:cover}.msg-avatar-placeholder[data-v-1a6c0445]{width:32px;height:32px;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:600;color:white}.msg-avatar-self[data-v-1a6c0445]{background:var(--accent-bg);color:var(--accent)}.message-bubble[data-v-1a6c0445]{padding:8px 12px;border-radius:12px;max-width:100%;word-break:break-word}.bubble-sticker[data-v-1a6c0445]{padding:4px;background:transparent !important}.bubble-self[data-v-1a6c0445]{background:var(--bg-bubble-self);border-bottom-right-radius:4px}.bubble-other[data-v-1a6c0445]{background:var(--bg-bubble-other);border-bottom-left-radius:4px}.message-content[data-v-1a6c0445]{font-size:13px;line-height:1.5;color:var(--text-primary)}.bubble-self .message-content[data-v-1a6c0445]{color:white}.sticker-img[data-v-1a6c0445]{width:96px;height:96px;object-fit:contain;display:block}[data-v-1a6c0445] .inline-sticker{width:24px;height:24px;vertical-align:middle;display:inline;margin:0 2px}.chat-empty[data-v-1a6c0445]{display:flex;align-items:center;justify-content:center;flex:1;min-height:120px}.chat-empty-text[data-v-1a6c0445]{font-size:13px;color:var(--text-muted)}.chat-input-bar[data-v-1a6c0445]{padding:8px 12px 6px;border-top:1px solid var(--border-secondary);flex-shrink:0;display:flex;flex-direction:column;gap:4px}.chat-input-wrapper[data-v-1a6c0445]{display:flex;align-items:center;gap:8px;background:var(--bg-input);border-radius:18px;padding:4px 4px 4px 14px}.chat-inp