`, "",{"version":3,"sources":["webpack://./src/小手机/components/AddContactModal.vue"],"names":[],"mappings":"AAuFA,gCACE,iBAAkB,CAClB,OAAQ,CACR,0BAA8B,CAC9B,YAAa,CACb,kBAAmB,CACnB,sBAAuB,CACvB,UAAW,CACX,yBACF,CAEA,8BACE,SAAU,CACV,eAAgB,CAChB,4BAA6B,CAC7B,sCAAuC,CACvC,kBAAmB,CACnB,eAAgB,CAChB,qCACF,CAEA,+BACE,YAAa,CACb,kBAAmB,CACnB,6BAA8B,CAC9B,sBACF,CAEA,8BACE,cAAe,CACf,eAAgB,CAChB,yBACF,CAEA,8BACE,UAAW,CACX,WAAY,CACZ,iBAAkB,CAClB,WAAY,CACZ,sBAAuB,CACvB,uBAAwB,CACxB,YAAa,CACb,kBAAmB,CACnB,sBAAuB,CACvB,cAAe,CACf,oBACF,CAEA,oCACE,0BAA2B,CAC3B,2BACF,CAEA,6BACE,qBACF,CAEA,8BACE,YAAa,CACb,qBAAsB,CACtB,OACF,CAEA,8BACE,cAAe,CACf,0BACF,CAEA,8BACE,UAAW,CACX,gBAAiB,CACjB,iBAAkB,CAClB,sCAAuC,CACvC,0BAA2B,CAC3B,yBAA0B,CAC1B,cAAe,CACf,YAAa,CACb,6BAA8B,CAC9B,qBACF,CAEA,oCACE,0BACF,CAEA,2CACE,sBACF,CAEA,4BACE,cAAe,CACf,cAAe,CACf,mBACF,CAEA,+BACE,YAAa,CACb,OAAQ,CACR,mBAAoB,CACpB,wBACF,CAEA,sBACE,gBAAiB,CACjB,iBAAkB,CAClB,WAAY,CACZ,cAAe,CACf,eAAgB,CAChB,cAAe,CACf,oBACF,CAEA,6BACE,0BAA2B,CAC3B,0BACF,CAEA,mCACE,2BAA4B,CAC5B,2BACF,CAEA,8BACE,wBAAyB,CACzB,WACF,CAEA,oCACE,8BACF,CAEA,uCACE,WAAY,CACZ,kBACF,CAGA,0EAEE,4BACF,CAEA,oGAEE,8BACF,CAEA,oEAEE,SACF,CAEA,gDACE,oBACF,CAEA,8CACE,oBACF","sourcesContent":["<template>\n  <Transition name=\"modal\">\n    <div v-if=\"store.showAddContact\" class=\"modal-overlay\" @click.self=\"close\">\n      <div class=\"modal-panel\">\n        <div class=\"modal-header\">\n          <span class=\"modal-title\">添加好友</span>\n          <button class=\"modal-close\" @click=\"close\">\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\">\n              <line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\" />\n              <line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\" />\n            </svg>\n          </button>\n        </div>\n\n        <div class=\"modal-body\">\n          <div class=\"input-group\">\n            <label class=\"input-label\">角色名称</label>\n            <input\n              ref=\"inputRef\"\n              v-model=\"contactName\"\n              class=\"input-field\"\n              placeholder=\"输入要添加的角色名...\"\n              @keydown.enter=\"handleAdd\"\n            />\n          </div>\n          <div v-if=\"errorMsg\" class=\"error-msg\">{{ errorMsg }}</div>\n        </div>\n\n        <div class=\"modal-footer\">\n          <button class=\"btn btn-cancel\" @click=\"close\">取消</button>\n          <button class=\"btn btn-confirm\" :class=\"{ disabled: !contactName.trim() }\" @click=\"handleAdd\">\n            添加\n          </button>\n        </div>\n      </div>\n    </div>\n  </Transition>\n</template>\n\n<script setup lang=\"ts\">\nimport { usePhoneStore } from '../store';\n\nconst store = usePhoneStore();\nconst inputRef = ref<HTMLInputElement | null>(null);\nconst contactName = ref('');\nconst errorMsg = ref('');\n\nwatch(() => store.showAddContact, (show) => {\n  if (show) {\n    contactName.value = '';\n    errorMsg.value = '';\n    nextTick(() => inputRef.value?.focus());\n  }\n});\n\nfunction close() {\n  store.showAddContact = false;\n  contactName.value = '';\n  errorMsg.value = '';\n}\n\nasync function handleAdd() {\n  const name = contactName.value.trim();\n  if (!name) {\n    errorMsg.value = '请输入角色名称';\n    return;\n  }\n\n  if (name === store.resolvedUserName) {\n    errorMsg.value = '不能添加自己为好友';\n    return;\n  }\n\n  if (store.contacts.some(c => c.name === name)) {\n    errorMsg.value = `「${name}」已在通讯录中`;\n    return;\n  }\n\n  errorMsg.value = '';\n  const success = await store.addContact(name);\n  if (success) {\n    close();\n  }\n}\n</script>\n\n<style scoped>\n.modal-overlay {\n  position: absolute;\n  inset: 0;\n  background: rgba(0, 0, 0, 0.5);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 10;\n  backdrop-filter: blur(4px);\n}\n\n.modal-panel {\n  width: 85%;\n  max-width: 280px;\n  background: var(--bg-primary);\n  border: 1px solid var(--border-primary);\n  border-radius: 14px;\n  overflow: hidden;\n  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);\n}\n\n.modal-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 14px 16px 10px;\n}\n\n.modal-title {\n  font-size: 15px;\n  font-weight: 600;\n  color: var(--text-primary);\n}\n\n.modal-close {\n  width: 24px;\n  height: 24px;\n  border-radius: 6px;\n  border: none;\n  background: transparent;\n  color: var(--text-muted);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: all 0.15s;\n}\n\n.modal-close:hover {\n  background: var(--bg-hover);\n  color: var(--text-secondary);\n}\n\n.modal-body {\n  padding: 4px 16px 12px;\n}\n\n.input-group {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.input-label {\n  font-size: 12px;\n  color: var(--text-tertiary);\n}\n\n.input-field {\n  width: 100%;\n  padding: 8px 12px;\n  border-radius: 8px;\n  border: 1px solid var(--border-primary);\n  background: var(--bg-input);\n  color: var(--text-primary);\n  font-size: 14px;\n  outline: none;\n  transition: border-color 0.15s;\n  box-sizing: border-box;\n}\n\n.input-field:focus {\n  border-color: var(--accent);\n}\n\n.input-field::placeholder {\n  color: var(--text-hint);\n}\n\n.error-msg {\n  margin-top: 8px;\n  font-size: 12px;\n  color: var(--danger);\n}\n\n.modal-footer {\n  display: flex;\n  gap: 8px;\n  padding: 0 16px 14px;\n  justify-content: flex-end;\n}\n\n.btn {\n  padding: 6px 16px;\n  border-radius: 8px;\n  border: none;\n  font-size: 13px;\n  font-weight: 500;\n  cursor: pointer;\n  transition: all 0.15s;\n}\n\n.btn-cancel {\n  background: var(--bg-hover);\n  color: var(--text-tertiary);\n}\n\n.btn-cancel:hover {\n  background: var(--bg-active);\n  color: var(--text-secondary);\n}\n\n.btn-confirm {\n  background: var(--accent);\n  color: white;\n}\n\n.btn-confirm:hover {\n  background: var(--accent-hover);\n}\n\n.btn-confirm.disabled {\n  opacity: 0.4;\n  cursor: not-allowed;\n}\n\n/* 过渡动画 */\n.modal-enter-active,\n.modal-leave-active {\n  transition: opacity 0.2s ease;\n}\n\n.modal-enter-active .modal-panel,\n.modal-leave-active .modal-panel {\n  transition: transform 0.2s ease;\n}\n\n.modal-enter-from,\n.modal-leave-to {\n  opacity: 0;\n}\n\n.modal-enter-from .modal-panel {\n  transform: scale(0.9);\n}\n\n.modal-leave-to .modal-panel {\n  transform: scale(0.9);\n}\n</style>\n"],"sourceRoot":""}]);
